/* @lc app=leetcode id=2671 lang=kotlin */ class FrequencyTracker(val f: IntArray = IntArray(100001), val ff: IntArray = IntArray(100001)) { fun add(n: Int) = f[n].also { if (it > 0) ff[it]-- }.run { f[n]++ }.run { ff[f[n]]++ } fun deleteOne(n: Int) = f[n].takeIf { it > 0 }?.also { ff[it]-- }?.also { f[n]-- }?.also { if (f[n] > 0) ff[f[n]]++ } fun hasFrequency(q: Int) = q in 0..100000 && ff[q] > 0 }